<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue';
import { useAuth } from '../auth';
import { productsApi } from '../api';
import { warehouseApi } from '../api/warehouse';
import { errorMessage } from '../api/http';
import { areaLanes, filterPallets, laneLabels } from '../utils/warehouse';
import { showDateTime } from '../utils/time';
import type { Product } from '../types';
import type { WarehouseArea, WarehousePallet, WarehouseOverview, WarehouseHistory } from '../types/warehouse';
import WarehousePalletForm from '../components/WarehousePalletForm.vue';
const {authenticated}=useAuth();
const data=ref<WarehouseOverview>({areas:[],pallets:[]}),products=ref<Product[]>([]),loading=ref(true),busy=ref(false),message=ref(''),notice=ref('');
const query=ref(''),areaId=ref<number>(),lane=ref(''),unknownOnly=ref(false);
const selectedArea=computed(()=>data.value.areas.find(a=>a.id===areaId.value));
const racks=computed(()=>data.value.areas.filter(a=>a.kind==='RACK'));
const aisles=computed(()=>data.value.areas.filter(a=>a.kind==='AISLE'));
const nearbyAisles=computed(()=>aisles.value.filter(a=>a.rackRow===selectedArea.value?.name));
const visible=computed(()=>filterPallets(data.value.pallets,query.value,areaId.value,lane.value,unknownOnly.value).sort((a,b)=>a.areaId-b.areaId||a.lane.localeCompare(b.lane)||a.position-b.position));
const uncounted=computed(()=>data.value.pallets.filter(p=>p.items.some(i=>i.quantity==null)).length);
const aisleCount=computed(()=>data.value.pallets.filter(p=>p.kind==='AISLE').length);
function count(id:number,l?:string){return data.value.pallets.filter(p=>p.areaId===id&&(!l||p.lane===l)).length}
function selectArea(id?:number,l=''){areaId.value=id;lane.value=l}
function clearFilters(){query.value='';selectArea();unknownOnly.value=false}
async function load(){loading.value=true;message.value='';try{data.value=await warehouseApi.overview()}catch(e){message.value=errorMessage(e)}finally{loading.value=false}}

const formDialog=ref<HTMLDialogElement>(),formKey=ref(0),editing=ref<WarehousePallet>(),initialArea=ref<number>(),initialLane=ref('LOWER'),continueEntry=ref(false);
async function openForm(pallet?:WarehousePallet){
  if(busy.value)return;busy.value=true;message.value='';continueEntry.value=false;
  try{products.value=await productsApi.search('',true)}catch{products.value=[];notice.value='已有产品列表暂时无法读取，仍可手动填写产品名称。'}
  editing.value=pallet;initialArea.value=pallet?.areaId||areaId.value||racks.value[0]?.id;initialLane.value=pallet?.lane||lane.value||(selectedArea.value?.kind==='AISLE'?'LEFT_1':'LOWER');formKey.value++;await nextTick();formDialog.value?.showModal();busy.value=false;
}
async function saved(pallet:WarehousePallet,another:boolean){
  const index=data.value.pallets.findIndex(p=>p.id===pallet.id);if(index<0)data.value.pallets.push(pallet);else data.value.pallets[index]=pallet;
  notice.value=`已保存 ${pallet.code} · ${pallet.location}`;
  if(another){initialArea.value=pallet.areaId;initialLane.value=pallet.lane;continueEntry.value=true;editing.value=undefined;formKey.value++;await nextTick();formDialog.value?.scrollTo({top:0});formDialog.value?.querySelector<HTMLInputElement>('input')?.focus()}else formDialog.value?.close();
}
async function remove(p:WarehousePallet){
  if(busy.value||!window.confirm(`确定移除托盘 ${p.code}？\n${p.location}\n会清空此货位并保留操作记录；不会自动新增物料流转单。`))return;
  busy.value=true;message.value='';try{await warehouseApi.remove(p.id,p.version);data.value.pallets=data.value.pallets.filter(row=>row.id!==p.id);notice.value=`已移除 ${p.code}`}catch(e){message.value=errorMessage(e)}finally{busy.value=false}
}

const aisleDialog=ref<HTMLDialogElement>(),aisleEditing=ref<WarehouseArea>(),aisleName=ref(''),aisleLanes=ref(2),aisleError=ref(''),aisleRackRow=ref('');
function resetAisle(){aisleEditing.value=undefined;aisleName.value='';aisleLanes.value=2;aisleRackRow.value=''}
async function openAisles(){resetAisle();aisleError.value='';await nextTick();aisleDialog.value?.showModal()}
function editAisle(a:WarehouseArea){aisleEditing.value=a;aisleName.value=a.name;aisleLanes.value=a.lanes;aisleRackRow.value=a.rackRow||'';aisleError.value=''}
async function saveAisle(){
  if(busy.value)return;busy.value=true;aisleError.value='';
  try{const fields={name:aisleName.value,lanes:aisleLanes.value,rackRow:aisleRackRow.value||null};const a=aisleEditing.value?await warehouseApi.updateAisle(aisleEditing.value.id,{...fields,version:aisleEditing.value.version}):await warehouseApi.createAisle(fields);await load();resetAisle();notice.value=`已保存过道 ${a.name}`;if(selectedArea.value&&!areaLanes(selectedArea.value).includes(lane.value))lane.value=''}catch(e){aisleError.value=errorMessage(e)}finally{busy.value=false}
}
async function removeAisle(a:WarehouseArea){
  if(busy.value||!window.confirm(`确定删除空过道“${a.name}”？`))return;busy.value=true;aisleError.value='';
  try{await warehouseApi.removeAisle(a.id,a.version);data.value.areas=data.value.areas.filter(row=>row.id!==a.id);if(areaId.value===a.id)selectArea();if(aisleEditing.value?.id===a.id)resetAisle()}catch(e){aisleError.value=errorMessage(e)}finally{busy.value=false}
}

const historyDialog=ref<HTMLDialogElement>(),history=ref<WarehouseHistory>(),historyPage=ref(0),historyId=ref<number>(),historyBusy=ref(false),historyError=ref('');
async function openHistory(id?:number){historyId.value=id;historyPage.value=0;history.value=undefined;await nextTick();historyDialog.value?.showModal();await loadHistory()}
async function loadHistory(){historyBusy.value=true;historyError.value='';try{history.value=await warehouseApi.history(historyPage.value,historyId.value)}catch(e){historyError.value=errorMessage(e)}finally{historyBusy.value=false}}
function historyState(value?:string):WarehousePallet|undefined{if(!value)return;try{return JSON.parse(value)}catch{return undefined}}
onMounted(load);
</script>
<template>
  <div class="page wide warehouse-page">
    <div class="warehouse-heading"><div><p class="eyebrow">货位 · 托盘 · 在库物料</p><h1 class="page-title">仓库管理</h1><p class="page-lead">先找到位置，再记录这托货。A–M 排货架与过道统一查询。</p></div><button v-if="authenticated" class="btn btn-primary" :disabled="loading||busy||!data.areas.length" @click="openForm()">＋ 录入托盘</button><RouterLink v-else class="btn btn-secondary" to="/login?redirect=/warehouse">登录后录入</RouterLink></div>
    <p v-if="message" class="error-text" role="alert">{{message}} <button class="btn btn-secondary" :disabled="loading" @click="load">重试</button></p>
    <p v-if="notice" class="notice" role="status">{{notice}}<button aria-label="关闭提示" @click="notice=''">×</button></p>
    <div class="warehouse-toolbar"><div class="inventory-counts"><span><b>{{data.pallets.length}}</b> 托已录入</span><span><b>{{aisleCount}}</b> 托在过道</span><span><b>{{uncounted}}</b> 托待盘点</span></div><div class="toolbar-actions"><button class="btn btn-ghost" :disabled="loading||busy" @click="load">刷新</button><button class="btn btn-ghost" @click="openHistory()">操作记录</button><button v-if="authenticated" class="btn btn-ghost" :disabled="busy" @click="openAisles">管理过道</button></div></div>
    <p class="hint scope-note">这里记录现场在库情况。录入、移位、移除托盘不会自动修改生产任务或流转记录；数量留空表示待盘点，不算作零库存。</p>
    <section class="location-board card" aria-labelledby="warehouse-map-title" :aria-busy="loading">
      <div class="board-heading"><h2 id="warehouse-map-title">货位看板</h2><span>点击排号或层位查看托盘 · 数字为已录入托盘数</span><button class="btn btn-secondary" :aria-pressed="!areaId" @click="selectArea()">全部库区</button></div>
      <p v-if="loading&&!data.areas.length" class="empty" role="status">正在读取仓库…</p>
      <div class="rack-scroll"><div class="rack-map"><div class="level-key" aria-hidden="true"><span>货架</span><span>上</span><span>中</span><span>下</span></div><div v-for="rack in racks" :key="rack.id" class="rack-column" :class="{selected:areaId===rack.id}"><button class="rack-letter" :aria-label="`${rack.name} 排全部，${count(rack.id)} 托`" :aria-pressed="areaId===rack.id&&!lane" @click="selectArea(rack.id)">{{rack.name}}</button><button v-for="l in areaLanes(rack)" :key="l" class="rack-cell" :class="{occupied:count(rack.id,l)>0}" :aria-pressed="areaId===rack.id&&lane===l" :aria-label="`${rack.name} 排${laneLabels[l]}，${count(rack.id,l)} 托`" @click="selectArea(rack.id,l)">{{count(rack.id,l)}}<span class="sr-only"> 托</span></button></div></div></div>
      <div v-if="nearbyAisles.length" class="nearby-links"><strong>{{selectedArea?.name}} 排旁过道</strong><button v-for="a in nearbyAisles" :key="a.id" class="btn btn-secondary" @click="selectArea(a.id)">{{a.name}} · {{a.lanes}} 排</button></div>
      <div class="aisle-map"><div v-for="a in aisles" :key="a.id" class="aisle-strip" :class="{selected:areaId===a.id}"><button class="aisle-title" :aria-pressed="areaId===a.id&&!lane" @click="selectArea(a.id)"><strong>{{a.rackRow ? `${a.rackRow} 排旁 · ` : ''}}{{a.name}}</strong><span>{{a.lanes===4?'四排（左一、左二、右一、右二）':'两排（左一、右一）'}} · {{count(a.id)}} 托</span></button><div class="aisle-lanes"><button v-for="l in areaLanes(a)" :key="l" :class="{second:l.endsWith('_2')}" :aria-pressed="areaId===a.id&&lane===l" @click="selectArea(a.id,l)"><span>{{laneLabels[l]}}</span><b>{{count(a.id,l)}}</b></button></div></div><p v-if="!loading&&!aisles.length" class="hint">尚未设置过道。登录后可新增并按现场名称命名。</p></div>
      <p class="map-note">未录入的位置显示 0，不代表已确认空位。货架位置序号按现场填写；过道左右以现场固定朝向为准。</p>
    </section>
    <section class="stock-results" aria-labelledby="stock-list-title">
      <div class="stock-filters"><div class="field"><label for="warehouse-search">查找物料或托盘</label><input id="warehouse-search" v-model="query" class="input" type="search" placeholder="产品名称、原料批号、批号、托盘号或位置"></div><label class="unknown-filter"><input v-model="unknownOnly" type="checkbox">只看待盘点</label></div>
      <div class="results-heading"><h2 id="stock-list-title">{{selectedArea ? `${selectedArea.name}${selectedArea.kind==='RACK'?' 排':''}${lane?' · '+laneLabels[lane]:''}` : '全部托盘'}} <span>{{visible.length}} 托</span></h2><button v-if="query||areaId||unknownOnly" class="btn btn-ghost" @click="clearFilters">清除筛选</button></div>
      <p v-if="!loading&&!visible.length" class="card empty">{{data.pallets.length?'没有符合条件的托盘，试试清除筛选。':'仓库还没有录入托盘。登录后，从第一个实际货位开始录入。'}}</p>
      <div class="pallet-grid"><article v-for="p in visible" :key="p.id" class="pallet-card card"><header><div class="location-tag" :class="{aisle:p.kind==='AISLE'}">{{p.location}}</div><span v-if="p.items.some(i=>i.quantity==null)" class="status warn">待盘点</span></header><div class="pallet-title"><h3 class="mono">{{p.code}}</h3><span>{{p.items.length}} 项物料</span></div><div v-for="(item,index) in p.items" :key="index" class="stored-item"><strong>{{item.productName}}</strong><a v-if="item.photoUrl" :href="item.photoUrl" target="_blank" rel="noopener" class="stock-photo"><img :src="item.photoUrl" :alt="`${item.productName}照片`" loading="lazy"></a><div class="item-identity"><span v-if="item.materialCode">{{item.materialCode}}</span><span>原料批号 {{item.rawMaterialBatch||'未录入'}}</span><span>批号 {{item.batch||'未录入'}}</span></div><div class="item-quantity"><b>{{item.quantity==null?'数量待盘点':item.quantity.toLocaleString()}}<small v-if="item.quantity!=null"> {{item.unit}}</small></b><span v-if="item.cartons!=null">{{item.cartons.toLocaleString()}} 箱</span></div></div><p v-if="p.notes" class="pallet-notes">{{p.notes}}</p><footer><span>更新 {{showDateTime(p.updatedAt)}}</span><div><button class="text-button" @click="openHistory(p.id)">记录</button><button v-if="authenticated" class="text-button" :disabled="busy" @click="openForm(p)">编辑 / 移位</button><button v-if="authenticated" class="text-button danger" :disabled="busy" @click="remove(p)">移除</button></div></footer></article></div>
    </section>

    <dialog ref="formDialog" class="warehouse-dialog" aria-label="托盘录入与编辑" @cancel.prevent><WarehousePalletForm v-if="authenticated" :key="formKey" :areas="data.areas" :pallets="data.pallets" :products="products" :pallet="editing" :initial-area-id="initialArea" :initial-lane="initialLane" :continue-entry="continueEntry" @saved="saved" @cancel="formDialog?.close()"/></dialog>
    <dialog ref="aisleDialog" class="warehouse-dialog" aria-labelledby="aisle-dialog-title" @cancel="busy&&$event.preventDefault()"><header class="dialog-heading"><div><h2 id="aisle-dialog-title">过道设置</h2><p class="hint">按现场命名，例如 A–B 之间、收货区过道。</p></div><button class="btn btn-secondary" :disabled="busy" @click="aisleDialog?.close()">关闭</button></header><p v-if="aisleError" class="error-text" role="alert">{{aisleError}}</p><div v-for="a in aisles" :key="a.id" class="aisle-setting"><div><strong>{{a.rackRow ? `${a.rackRow} 排旁 · ` : ''}}{{a.name}}</strong><span>{{a.lanes}} 排 · {{count(a.id)}} 托</span></div><button class="btn btn-secondary" :disabled="busy" @click="editAisle(a)">编辑</button><button class="btn btn-danger" :disabled="busy||count(a.id)>0" @click="removeAisle(a)">删除</button></div><form class="aisle-form" @submit.prevent="saveAisle"><h3>{{aisleEditing?'编辑过道':'新增过道'}}</h3><div class="field"><label for="aisle-name">过道名称</label><input id="aisle-name" v-model="aisleName" class="input" required maxlength="60" :disabled="busy"></div><div class="field"><label for="aisle-rack">位于哪一排旁（可选）</label><select id="aisle-rack" v-model="aisleRackRow" class="select" :disabled="busy" @change="aisleRackRow==='A'&&(aisleLanes=4)"><option value="">独立过道</option><option v-for="r in racks" :key="r.id" :value="r.name">{{r.name}} 排旁</option></select></div><div class="field"><label for="aisle-lanes">可放排数</label><select id="aisle-lanes" v-model="aisleLanes" class="select" :disabled="busy||aisleRackRow==='A'"><option :value="2">两排：左一、右一</option><option :value="4">四排：左一、左二、右一、右二</option></select></div><p class="hint">第二排有托盘时不能缩为两排；过道有托盘时不能删除。</p><div class="toolbar-actions"><button v-if="aisleEditing" type="button" class="btn btn-secondary" :disabled="busy" @click="resetAisle">取消编辑</button><button class="btn btn-primary" :disabled="busy">{{busy?'正在保存…':'保存过道'}}</button></div></form></dialog>
    <dialog ref="historyDialog" class="warehouse-dialog" aria-labelledby="warehouse-history-title"><header class="dialog-heading"><h2 id="warehouse-history-title">{{historyId?'托盘操作记录':'仓库操作记录'}}</h2><button class="btn btn-secondary" @click="historyDialog?.close()">关闭</button></header><p v-if="historyError" class="error-text" role="alert">{{historyError}} <button class="text-button" @click="loadHistory">重试</button></p><p v-if="historyBusy" role="status">正在读取…</p><template v-else><p v-if="!history?.content.length" class="empty">暂无操作记录。</p><article v-for="event in history?.content" :key="event.id" class="history-event"><time>{{showDateTime(event.createdAt)}}</time><h3>{{event.description}}</h3><span v-if="event.palletCode" class="mono">{{event.palletCode}}</span><details v-if="event.beforeState||event.afterState"><summary>查看变更前后物料</summary><div v-for="(state,index) in [historyState(event.beforeState),historyState(event.afterState)]" :key="index"><template v-if="state"><h4>{{index===0?'变更前':'变更后'}} · {{state.location}}</h4><p v-for="(item,n) in state.items" :key="n">{{item.productName}}<template v-if="item.materialCode"> · {{item.materialCode}}</template> · 原料批号 {{item.rawMaterialBatch||'未录入'}} · 批号 {{item.batch||'未录入'}} · {{item.quantity==null?'待盘点':`${item.quantity.toLocaleString()} ${item.unit||''}`}}<template v-if="item.cartons!=null"> · {{item.cartons}} 箱</template><a v-if="item.photoUrl" :href="item.photoUrl" target="_blank" rel="noopener" class="stock-photo"><img :src="item.photoUrl" :alt="`${item.productName}照片`" loading="lazy"></a></p><p v-if="state.notes">备注：{{state.notes}}</p></template></div></details></article></template><div v-if="history&&history.totalPages>1" class="history-pages"><button class="btn btn-secondary" :disabled="historyBusy||historyPage===0" @click="historyPage--;loadHistory()">上一页</button><span>{{historyPage+1}} / {{history.totalPages}}</span><button class="btn btn-secondary" :disabled="historyBusy||historyPage+1>=history.totalPages" @click="historyPage++;loadHistory()">下一页</button></div></dialog>
  </div>
</template>
<style scoped>
.warehouse-page{--rack-steel:#174a68;--rack-beam:#b75b18}.warehouse-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.warehouse-heading>.btn{flex-shrink:0}.eyebrow{font-size:11px;letter-spacing:.12em;color:var(--muted);margin:0 0 8px}.warehouse-toolbar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;padding:14px 0;border-block:1px solid var(--line)}.inventory-counts{display:flex;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:12px}.inventory-counts b{font:700 22px Consolas,monospace;color:var(--blue);margin-right:4px}.toolbar-actions{display:flex;gap:6px;flex-wrap:wrap}.scope-note{margin:12px 0 20px}.notice{display:flex;justify-content:space-between;align-items:center;background:var(--soft-green);color:var(--green);padding:10px 14px;font-size:13px;border-radius:8px}.notice button{border:0;background:none;font-size:22px;min-width:36px;min-height:36px;cursor:pointer}.location-board{overflow:hidden}.board-heading{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:16px 18px}.board-heading h2{font-size:16px;margin:0}.board-heading>span{font-size:12px;color:var(--muted)}.board-heading .btn{margin-left:auto}.rack-scroll{overflow-x:auto;padding:0 18px 16px}.rack-map{display:grid;grid-template-columns:26px repeat(13,minmax(44px,1fr));gap:5px;min-width:700px}.level-key,.rack-column{display:grid;grid-template-rows:38px repeat(3,42px);gap:4px}.level-key{font-size:11px;color:var(--muted);text-align:center;align-items:center}.rack-column{padding:0 3px 5px;border-inline:2px solid #b7c8d2;border-bottom:3px solid var(--rack-beam);background:#f5f8fa}.rack-column.selected{border-inline-color:var(--rack-steel)}.rack-column button{border:0;cursor:pointer}.rack-letter{font:700 23px Consolas,monospace;color:var(--blue);background:transparent}.rack-cell{font:600 15px Consolas,monospace;background:#e9eef0;color:#71828c;border-bottom:2px solid #c0cdd4!important;border-radius:3px}.rack-cell.occupied{background:#d9eaf0;color:var(--blue)}.rack-column button[aria-pressed=true]{background:var(--blue);color:white}.aisle-map{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:16px 18px;background:#f7f9fa;border-top:1px solid var(--line)}.aisle-strip{background:white;border:1px solid var(--line);border-radius:8px;padding:12px}.aisle-strip.selected{border-color:var(--green)}.aisle-title{display:flex;justify-content:space-between;flex-wrap:wrap;align-items:center;gap:6px;width:100%;border:0;background:none;text-align:left;padding:0 0 8px;min-height:36px;cursor:pointer}.aisle-title strong{font-size:14px}.aisle-title span{font-size:11px;color:var(--muted)}.aisle-lanes{display:flex;gap:6px}.aisle-lanes button{flex:1;display:flex;align-items:center;justify-content:space-between;gap:5px;min-height:42px;border:1px solid #bcd2cd;background:#eef6f3;border-radius:5px;padding:8px;color:var(--green);cursor:pointer;font-size:12px}.aisle-lanes button.second{border-style:dashed;background:#fbf5ed;color:#8c542c}.aisle-lanes button[aria-pressed=true]{background:var(--green);color:white}.aisle-lanes b{font:700 17px Consolas,monospace}.map-note{margin:0;padding:0 18px 14px;background:#f7f9fa;color:var(--muted);font-size:11px;line-height:1.6}.stock-results{margin-top:24px}.stock-filters{display:flex;align-items:end;gap:18px}.stock-filters>.field{flex:1}.unknown-filter{display:flex;align-items:center;gap:7px;min-height:44px;font-size:13px;white-space:nowrap}.unknown-filter input{width:17px;height:17px;accent-color:var(--blue)}.results-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:20px 0 12px}.results-heading h2{font-size:17px;margin:0}.results-heading h2 span{font-size:12px;font-weight:400;margin-left:10px;color:var(--muted)}.pallet-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.pallet-card{padding:16px;min-width:0}.pallet-card header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wr